// Basic test for replaceIf functionality
const arr = [1, 2, 3, 4, 5];
console.log("Original array:", arr);

// Replace element at index 2 (value 3) with 99 if the element is equal to 3
const replaced = arr.replaceIf(2, (e) => e === 3, 99);
console.log("Replace result:", replaced);
console.log("Modified array:", arr);

// Try replacing with a condition that fails
const notReplaced = arr.replaceIf(3, (e) => e === 99, 100);
console.log("Failed replace result:", notReplaced);
console.log("Array after failed replace:", arr);

// Test with a callback that modifies the array
const arr2 = [10, 20, 30, 40, 50];
console.log("\nSecond array test:", arr2);
const modified = arr2.replaceIf(2, (e) => {
  // Modify the array during callback
  arr2.push(60);
  console.log("Array during callback:", arr2);
  return true;
}, 999);
console.log("Modified array result:", modified);
console.log("Final array state:", arr2);

// Testing possible vulnerability in replaceIf
const arr = [1, 2, 3, 4, 5];

// Test 1: Modify the array length during callback to be shorter than the index
console.log("Test 1: Shortening array during callback");
console.log("Original array:", arr);
const result1 = arr.replaceIf(3, (e) => {
  console.log("Element at index 3:", e);
  // Make array shorter than the index
  arr.length = 3; 
  console.log("Array during callback:", arr);
  return true;
}, 99);
console.log("Replace result:", result1);
console.log("Array after operation:", arr);

// Reset array
arr.length = 5;
arr[0] = 1; arr[1] = 2; arr[2] = 3; arr[3] = 4; arr[4] = 5;

// Test 2: Try to exploit proxy behavior
console.log("\nTest 2: Testing with proxy");
const proxyArr = new Proxy(arr, {
  get: function(target, prop) {
    console.log("Getting property:", prop);
    if (prop === "length") {
      // Return different values for length checks
      console.log("Modifying length on access");
      return 5; // First time return 5, next time could return less
    }
    return target[prop];
  }
});

console.log("Original proxy array:", proxyArr);
const result2 = proxyArr.replaceIf(3, (e) => {
  console.log("Element at callback:", e);
  return true;
}, 999);
console.log("Replace result:", result2);
console.log("Array after operation:", arr);

