// Basic test of replaceIf functionality
let arr = [1, 2, 3, 4, 5];
console.log("Original array:", arr);

// Replace element at index 2 if it's equal to 3
let result1 = arr.replaceIf(2, (element) => element === 3, 30);
console.log("Result of first replacement:", result1);
console.log("Array after first replacement:", arr);

