// Basic functionality test
console.log("===== Basic Functionality Test =====");
let arr = [1, 2, 3, 4, 5];
console.log("Original array:", arr);

// Test 1: Replace element at index 2 with 99 if element equals 3
let result = arr.replaceIf(2, function(e) { 
    console.log("Callback received:", e);
    return e === 3;
}, 99);

console.log("Replace result:", result);
console.log("Array after replace:", arr);

// Test 2: Try to replace an element that doesn't match condition
result = arr.replaceIf(2, function(e) {
    console.log("Callback received:", e);
    return e === 3; // Element is now 99, so this should return false
}, 100);

console.log("Replace result (should be false):", result);
console.log("Array (should be unchanged):", arr);

// Testing the vulnerability: Array modification during callback
console.log("\n===== Array Modification During Callback Test =====");
let arr2 = [1, 2, 3, 4, 5];
console.log("Original array:", arr2);

// Try to modify the array during the callback
result = arr2.replaceIf(2, function(e) {
    console.log("Callback received:", e);

    // Modify the array during callback
    arr2.length = 0; // Clear the array
    console.log("Array during callback:", arr2);

    return true; // We want to replace
}, 999);

console.log("Replace result:", result);
console.log("Final array:", arr2);

// Type confusion test
console.log("\n===== Type Confusion Test =====");
let arr3 = [1, 2, {value: 3}, 4, 5];
console.log("Original array:", JSON.stringify(arr3));

// Try to cause type confusion
result = arr3.replaceIf(2, function(obj) {
    console.log("Callback received:", JSON.stringify(obj));

    // Modify the object during callback
    if (obj && typeof obj === 'object') {
        obj.value = "modified";
    }

    return true;
}, {new: "object"});

console.log("Replace result:", result);
console.log("Final array:", JSON.stringify(arr3));

// Test with proxy object
console.log("\n===== Test with Proxy Object =====");
let targetArray = [1, 2, 3, 4, 5];
let proxyHandler = {
    get: function(target, prop) {
        console.log("Proxy get:", prop);
        return target[prop];
    },
    set: function(target, prop, value) {
        console.log("Proxy set:", prop, "=", value);
        target[prop] = value;
        return true;
    }
};

let proxyArray = new Proxy(targetArray, proxyHandler);
console.log("Original proxy array:", proxyArray);

result = proxyArray.replaceIf(2, function(e) {
    console.log("Callback received:", e);
    return true;
}, 888);

console.log("Replace result:", result);
console.log("Final array:", targetArray);

