// Test for replaceIf vulnerability
console.log("Testing replaceIf functionality and potential vulnerabilities");

// Basic functionality test
function basicTest() {
  console.log("=== Basic functionality test ===");
  let arr = [1, 2, 3, 4, 5];
  console.log("Original array:", arr);

  // Replace element at index 2 if it equals 3
  const result = arr.replaceIf(2, function(element) {
    console.log("Callback called with element:", element);
    return element === 3;
  }, 99);

  console.log("Result:", result);
  console.log("Modified array:", arr);
}

// Test with proxy
function proxyTest() {
  console.log("\n=== Proxy test ===");
  let arr = [1, 2, 3, 4, 5];

  // Create a proxy around the array
  let proxy = new Proxy(arr, {
    get: function(target, prop) {
      console.log("Proxy get:", prop);
      return target[prop];
    },
    set: function(target, prop, value) {
      console.log("Proxy set:", prop, "=", value);
      target[prop] = value;
      return true;
    }
  });

  console.log("Original array via proxy:", proxy);

  // Replace element using proxy
  const result = proxy.replaceIf(2, function(element) {
    console.log("Callback called with element:", element);
    return element === 3;
  }, 99);

  console.log("Result:", result);
  console.log("Modified array via proxy:", proxy);
  console.log("Actual array:", arr);
}

// Test length changes during callback
function lengthChangeTest() {
  console.log("\n=== Length change during callback test ===");
  let arr = [1, 2, 3, 4, 5];
  console.log("Original array:", arr);

  // Try to replace element at index 2, but modify the array during callback
  const result = arr.replaceIf(2, function(element) {
    console.log("Callback called with element:", element);
    // Modify the array during callback
    arr.length = 2; // Truncate the array
    console.log("Array length changed to:", arr.length);
    return true;
  }, 99);

  console.log("Result:", result);
  console.log("Final array:", arr);
}

// Test changing target array's identity during callback
function identityChangeTest() {
  console.log("\n=== Array identity change test ===");
  let arr = [1, 2, 3, 4, 5];
  let proxy = new Proxy(arr, {});

  console.log("Original array:", arr);

  // Try to replace element at index 2, but modify the proxy's target during callback
  try {
    const result = proxy.replaceIf(2, function(element) {
      console.log("Callback called with element:", element);
      // Change the target of the proxy
      let newArr = [10, 20, 30];
      // This code would normally cause an error as you can't change a proxy's target
      // In a real exploit, we'd need a different approach to change the target array
      console.log("Would try to change proxy target from", arr, "to", newArr);
      return true;
    }, 99);

    console.log("Result:", result);
  } catch (e) {
    console.log("Error:", e);
  }
  console.log("Final array:", arr);
}

// Run all tests
basicTest();
proxyTest();
lengthChangeTest();
identityChangeTest();

